import os
import google.auth
from google.cloud import monitoring_v3

def filter_metric_dimensions(payload, config=None):
    config = config or {}
    project_id = config.get('project_id')
    filter_expression = payload.get('filter_expression')
    metric_descriptor_name = config.get('metric_descriptor_name')
    filter_dimensions = payload.get('filter_dimensions')

    credentials, _ = google.auth.default()
    client = monitoring_v3.MetricServiceClient(credentials=credentials)

    request = monitoring_v3.ListMetricDescriptorsRequest(
        name=f"projects/{project_id}",
        filter=metric_descriptor_name
    )
    metric_descriptors = client.list_metric_descriptors(request=request).metric_descriptors

    for descriptor in metric_descriptors:
        if metric_descriptor_name in descriptor.type:
            for dimension in descriptor.dimension_values:
                if dimension.key in filter_dimensions:
                    filter_value = dimension.values[0]
                    if filter_value == filter_expression:
                        return filter_value

    return None
